import SwiftUI
import TrainingEngine

/// Front and back figures with the movement's primary muscle in the accent and the
/// secondary muscles in a dimmer blue. Layers are generated by scripts/generate_movement_art.py.
struct MuscleMap: View {
    let primary: MuscleGroup
    let secondary: [MuscleGroup]
    var sides: [Side] = Side.allCases

    enum Side: String, CaseIterable { case front, back }

    /// The side a muscle reads best from, for places with room for one figure.
    static func side(showing group: MuscleGroup) -> Side {
        switch group {
        case .back, .hamstrings, .glutes, .triceps: .back
        default: .front
        }
    }

    /// The muscle layers each side has art for; the rest of the body is in the base layer.
    private static let layers: [Side: [MuscleGroup]] = Dictionary(uniqueKeysWithValues: Side.allCases.map { side in
        (side, MuscleGroup.allCases.filter { UIImage(named: assetName(side, $0.rawValue)) != nil })
    })

    private static func assetName(_ side: Side, _ layer: String) -> String { "BodyMap/\(side.rawValue)-\(layer)" }

    var body: some View {
        HStack(spacing: 6) {
            ForEach(sides, id: \.self) { figure($0) }
        }
        .accessibilityElement()
        .accessibilityLabel(accessibilityText)
    }

    private func figure(_ side: Side) -> some View {
        ZStack {
            layer(Self.assetName(side, "base"), tint: Self.untrained)
            ForEach(Self.layers[side] ?? [], id: \.self) { group in
                layer(Self.assetName(side, group.rawValue), tint: tint(for: group))
            }
        }
    }

    private func layer(_ name: String, tint: Color) -> some View {
        Image(name).resizable().renderingMode(.template).scaledToFit().foregroundStyle(tint)
    }

    private func tint(for group: MuscleGroup) -> Color {
        if group == primary { return Self.primaryTint }
        return secondary.contains(group) ? Self.secondaryTint : Self.untrained
    }

    static let primaryTint = Palette.accent
    static let secondaryTint = Palette.accent.opacity(0.5)
    static let untrained = Color.white.opacity(0.11)

    private var accessibilityText: String {
        let also = secondary.map { $0.displayName.lowercased() }
        return also.isEmpty ? "Works the \(primary.displayName.lowercased())" : "Works the \(primary.displayName.lowercased()), also \(also.formatted(.list(type: .and)))"
    }
}

/// An Everkinetic line drawing of the movement, relaxed then tensed, in the ink colour.
/// Only movements whose drawing shows them as programmed have one.
struct MovementDrawing: View {
    let exercise: Exercise

    static func isAvailable(for exercise: Exercise) -> Bool {
        UIImage(named: assetName(exercise.id, "tension")) != nil
    }

    static func assetName(_ id: String, _ frame: String) -> String { "Movement/\(id)-\(frame)" }

    var body: some View {
        HStack(spacing: 16) {
            ForEach(["relaxation", "tension"], id: \.self) { frame in
                Image(Self.assetName(exercise.id, frame))
                    .resizable()
                    .renderingMode(.template)
                    .scaledToFit()
                    .foregroundStyle(Palette.ink.opacity(0.88))
                    .frame(maxWidth: .infinity)
            }
        }
        .accessibilityElement()
        .accessibilityLabel("Drawing of \(exercise.name), relaxed and tensed")
    }
}

/// A square tile for lists of movements: the tensed drawing, or for movements without one,
/// the half of the muscle map that holds the primary muscle, large enough to read.
struct MovementThumbnail: View {
    let exercise: Exercise
    var size: CGFloat = 64

    private static let legs: Set<MuscleGroup> = [.quads, .hamstrings, .glutes, .calves]

    var body: some View {
        let shape = RoundedRectangle(cornerRadius: size * 0.22, style: .continuous)
        Group {
            if MovementDrawing.isAvailable(for: exercise) {
                Image(MovementDrawing.assetName(exercise.id, "tension"))
                    .resizable()
                    .renderingMode(.template)
                    .scaledToFit()
                    .foregroundStyle(Palette.ink.opacity(0.88))
                    .padding(5)
            } else {
                let showsLegs = Self.legs.contains(exercise.primary)
                // 1.8 times the tile shows head to hips, or hips to feet.
                MuscleMap(primary: exercise.primary, secondary: exercise.secondary, sides: [MuscleMap.side(showing: exercise.primary)])
                    .frame(height: size * 1.8)
                    .offset(y: showsLegs ? -4 : 4)
                    .frame(width: size, height: size, alignment: showsLegs ? .bottom : .top)
            }
        }
        .frame(width: size, height: size)
        .clipShape(shape)
        .background { shape.fill(Palette.canvas) }
        .overlay { shape.strokeBorder(Palette.hairline) }
        .accessibilityHidden(true)
    }
}

/// The drawing, when there is one, over the muscle map and its key.
struct MovementVisual: View {
    let exercise: Exercise

    var body: some View {
        VStack(spacing: 20) {
            if MovementDrawing.isAvailable(for: exercise) {
                MovementDrawing(exercise: exercise).frame(height: 150)
                Rectangle().fill(Palette.hairline).frame(height: 1)
            }
            HStack(alignment: .center, spacing: 20) {
                // The map takes the width its figures need at full height; the key gets the rest.
                MuscleMap(primary: exercise.primary, secondary: exercise.secondary).frame(height: 180).layoutPriority(1)
                VStack(alignment: .leading, spacing: 12) {
                    key(tint: MuscleMap.primaryTint, title: "Works", value: exercise.primary.displayName)
                    if !exercise.secondary.isEmpty {
                        key(tint: MuscleMap.secondaryTint, title: "Also", value: alsoText)
                    }
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                .accessibilityHidden(true)
            }
        }
    }

    /// "Triceps and shoulders": sentence case, so only the first muscle is capitalised.
    private var alsoText: String {
        let names = exercise.secondary.enumerated().map { $0.offset == 0 ? $0.element.displayName : $0.element.displayName.lowercased() }
        return names.formatted(.list(type: .and))
    }

    private func key(tint: Color, title: String, value: String) -> some View {
        HStack(alignment: .top, spacing: 8) {
            Circle().fill(tint).frame(width: 8, height: 8).padding(.top, 4.5)
            VStack(alignment: .leading, spacing: 2) {
                Text(title).font(.label).foregroundStyle(Palette.inkTertiary)
                Text(value).font(.body2).foregroundStyle(Palette.ink).fixedSize(horizontal: false, vertical: true)
            }
        }
    }
}
